local seat_uid= -1
local LowerScoreScene = class("LowerScoreScene")
local position ={}
local gold = 0
local chip_position = {}
function LowerScoreScene:initData()


end

function LowerScoreScene:init()
    dump("LowerScoreScene====")
    self:removeScene()
    self.LowerScoreScene = cc.CSLoader:createNode("sangong/csb/LowerScoreScene.csb")
    SCENENOW["scene"]:addChild(self.LowerScoreScene,999)
    self.LowerScoreScene:setName("LowerScoreScene"):setScale(1280/1920)
    self.LowerScore = self.LowerScoreScene:getChildByName("LowerScore")
    self.panel =  self.LowerScoreScene:getChildByName("panel")
    self.LowerScore:getChildByName("content_lv"):removeAllItems()
    local foot_panel =self.LowerScore:getChildByName("foot_panel")
    local chip_bg = foot_panel:getChildByName("chip_bg")
    if chip_bg then
        self.text_gold = chip_bg:getChildByName("text_gold")
    end
    self.btn_close = foot_panel:getChildByName("btn_close")
    self.btn_confirm = foot_panel:getChildByName("btn_confirm")
    self.btn_clear = foot_panel:getChildByName("btn_clear")
    self.btn_allin = foot_panel:getChildByName("btn_allin")
    local title=self.LowerScore:getChildByName("title")
    title:setTouchEnabled(true)
    title:addTouchEventListener(function(sender,event)
        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            SanGongSendHandle:CLIENT_CMD_REQ_TEST()
            title:setTouchEnabled(false)
        end
    end)
    local function touchButtonEvent(sender,event)
        --触摸开始
        if event == TOUCH_EVENT_BEGAN then
            sender:setScale(0.9)
        end

        --触摸取消
        if event == TOUCH_EVENT_CANCELED then
            sender:setScale(1.0)
        end

        --触摸结束
        if event == TOUCH_EVENT_ENDED then
            sender:setScale(1.0)
            if sender.type == 1 then
                if self.text_gold then
                    local number = self.text_gold:getString()
                    dump(number,"number")
                    dump(seat_uid,"seat_uid")
                    local value = 0
                    if isRide then
                        value = number*100
                    else
                        value = number
                    end
                    if tonumber(GAME_UID_YA) > 0 and tonumber(value) > 0 then
                        SanGongSendHandle:CLIENT_CMD_YA(GAME_UID_YA,value)
                    end

                end
            elseif sender.type == 2 then
                gold = sender.gold
                chip_position = sender:getPosition()
                local number = tonumber(self.text_gold:getString())
                local gold = SanGongUtils:goldMath(sender.gold)
                self.text_gold:setString(gold+number)
            elseif sender.type == 3 then
                self:removeScene()
            elseif sender.type == 4 then
                self.text_gold:setString(0)
            elseif sender.type == 6 then
                local gold = math.floor(SANGONG_USERINFO_TABLE[USER_INFO["uid"]].gold)
                self.text_gold:setString(gold)
            end

        end
    end
    print(GAME_CHIP_CONFIG,"GAME_CHIP_CONFIG")
    for k,v in ipairs(GAME_CHIP_CONFIG) do
        dump(v,"GAME_CHIP_CONFIG")
        local btn_chip = foot_panel:getChildByName("btn_chip_"..k)
        btn_chip:removeAllChildren()
        if k == 1 then
            gold = v
            chip_position = btn_chip:getPosition()
        end
        local text = SanGongUtils:getChipBtnText(SanGongUtils:goldMath(v))
        text:setPosition(cc.p(btn_chip:getContentSize().width/2 -2,btn_chip:getContentSize().height/2 +5))
        btn_chip:addChild(text)
        btn_chip.gold = v
        btn_chip.type =2
        btn_chip:addTouchEventListener(touchButtonEvent)
    end
    self.btn_confirm.type = 1
    self.btn_confirm:addTouchEventListener(touchButtonEvent)
    self.btn_close.type = 3
    self.btn_close:addTouchEventListener(touchButtonEvent)
    self.btn_clear.type = 4
    self.btn_clear:addTouchEventListener(touchButtonEvent)
    self.btn_allin.type =6
    self.btn_allin:addTouchEventListener(touchButtonEvent)


end
function LowerScoreScene:removeScene()
    --if self.LowerScoreScene == nil or tolua.isnull(self.LowerScoreScene)then
    --    self:init()
    --end
    --self.LowerScoreScene:setVisible(false)
    --self.LowerScore:getChildByName("content_lv"):removeAllItems()

    require(TpackageName..".Control"):removeScene()
    local s = SCENENOW["scene"]:getChildByName("LowerScoreScene")
    if s then
        s:removeSelf()
    end
end

function LowerScoreScene:showLowerScoreScene(pack)
    if self.LowerScoreScene == nil or tolua.isnull(self.LowerScoreScene)then
        return
    end
    self.LowerScoreScene:setLocalZOrder(9999)
    local content_lv =  self.LowerScore:getChildByName("content_lv")
    local index = 1
    local count = 0
    local panel
    for i,v in pairs(pack.countArr) do
        local item
        local  index = (count % 4)
        if index == 0 then
            panel =  self.panel:clone()
            item = panel:getChildByName("item_"..index)
            content_lv:pushBackCustomItem(panel)
        else
            item = panel:getChildByName("item_"..index)
        end

        if item then
            item:setVisible(true)
        end
        local score = item:getChildByName("score")
        local nick = item:getChildByName("nick")
        local no = item:getChildByName("no")
        local time_text = item:getChildByName("time_text")
        nick:setString(SanGongUtils:formatNick(v.nickName or "", 4))
        no:setString(v.no)
        time_text:setString(v.time)
        score:setString(SanGongUtils:goldMath(v.zhu))

        local head = display.newSprite("sangong/images/over/kong.png")
        head:addTo(item)
        head:setPosition(41.84, 41.84)
        local userinfo = {
            icon_url = v.portrait
        }
        local head_info = {}
        head_info["icon_url"] =   v.portrait or DefaultHead_filePath
        head_info["uid"] = v.uid
        head_info["sex"] = v["sex"] or 1
        head_info["sp"] = head
        head_info["size"] = 65
        head_info["touchable"] = 0
        head_info["use_sharp"] = 1
        require("hall.GameCommon"):setPlayerHead(head_info, head, 65)
        count = count + 1
    end

end

function LowerScoreScene:showScene()

end

function LowerScoreScene:clearGoldPanel()
    self.gold_panel:removeAllChildren()
end

return LowerScoreScene